### Simple Caching Implementation

```javascript
class WeatherCache {
  constructor(ttl = 3600000) { // Default TTL: 1 hour
    this.cache = {};
    this.ttl = ttl;
  }

  get(city) {
    const entry = this.cache[city];
    if (entry && entry.expires > Date.now()) {
      return entry.data;
    }
    return null;
  }

  set(city, data) {
    this.cache[city] = {
      data,
      expires: Date.now() + this.ttl
    };
  }
}

class RateLimiter {
  constructor(limit, interval) {
    this.limit = limit;
    this.interval = interval;
    this.calls = [];
  }

  canCall() {
    const now = Date.now();
    // Remove calls older than the interval (e.g., last 24 hours)
    this.calls = this.calls.filter(call => now - call <= this.interval);
    return this.calls.length < this.limit;
  }

  recordCall() {
    this.calls.push(Date.now());
  }
}

