  // 1. Check cache first
  const cachedResponse = cache.get(city);
  if (cachedResponse) {
    return cachedResponse;
  }

  // 2. Check rate limit
  if (!rateLimiter.canCall()) {
    console.warn('Rate limit exceeded. Serving stale data or null.');
    // Optional: Return stale data if you want a fallback
    return null;
  }

  try {
    // 3. Fetch from API
    const response = await fetch(
      `https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=${process.env.OPENWEATHER_API_KEY}`
    );

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const jsonData = await response.json();

    // 4. Store in cache and record the call
    cache.set(city, jsonData);
    rateLimiter.recordCall();

    return jsonData;
  } catch (error) {
    console.error('Error fetching weather:', error);
    return null;
  }
}

// Example usage
fetchWeather('London').then(data => {
  if (data) {
    console.log('Weather data:', data);
  } else {
    console.log('No data available (cache miss + rate limit or error).');
  }
});
```

